int led1 = 8;
int led2 = 9;
int led3 = 10;
int buttonPin = 2;

void setup() {
  pinMode(led1, OUTPUT);
  pinMode(led2, OUTPUT);
  pinMode(led3, OUTPUT);

  // Включаем внутренний резистор. Теперь пин 2 всегда притянут к 5V,
  // если его ничто не тянет к земле. Случайных нажатий не будет.
  pinMode(buttonPin, INPUT_PULLUP); 

  randomSeed(analogRead(0));
}

void loop() {
  // Кнопка подключена к GND. При нажатии на пине будет LOW (0).
  if (digitalRead(buttonPin) == LOW) {

    // === ЗАЩИТА ОТ ДРЕБЕЗГА И ДВОЙНОГО НАЖАТИЯ ===
    delay(50); 
    if (digitalRead(buttonPin) == LOW) { // Проверяем еще раз через 50мс

      // 1. Эффект рулетки
      for (int i = 0; i < 15; i++) {
        digitalWrite(led1, HIGH); delay(50); digitalWrite(led1, LOW);
        digitalWrite(led2, HIGH); delay(50); digitalWrite(led2, LOW);
        digitalWrite(led3, HIGH); delay(50); digitalWrite(led3, LOW);
      }

      // 2. Выбор победителя
      int winner = random(8, 11); 
      digitalWrite(winner, HIGH); // Зажигаем победителя

      // 3. Ждем, пока кнопку ОТПУСТЯТ
      // Пока кнопка нажата (LOW), программа стоит на месте.
      while(digitalRead(buttonPin) == LOW) {
        delay(10); 
      }

      // 4. Ждем, пока кнопку нажмут СНОВА, чтобы начать новый раунд
      // Пока кнопка НЕ нажата (HIGH), программа стоит на месте.
      // Светодиод победителя продолжает гореть!
      while(digitalRead(buttonPin) == HIGH) {
        delay(10); 
      }

      // 5. Когда кнопку нажали снова - гасим победителя и начинаем заново
      digitalWrite(8, LOW);
      digitalWrite(9, LOW);
      digitalWrite(10, LOW);

      // Небольшая пауза, чтобы цикл не начался мгновенно
      delay(200); 
    }
  }
}
